int charger_can_raw_elcon_interface_status_pack(
    uint8_t *dst_p,
    const struct charger_can_raw_elcon_interface_status_t *src_p,
    size_t size)
{
    if (size < 4u) {
        return (-EINVAL);
    }

    memset(&dst_p[0], 0, 4);

    dst_p[0] |= pack_left_shift_u8(src_p->status, 0u, 0x01u);
    dst_p[0] |= pack_left_shift_u8(src_p->fault_elcon_watchdog, 1u, 0x02u);
    dst_p[0] |= pack_left_shift_u8(src_p->fault_bps_watchdog, 2u, 0x04u);
    dst_p[0] |= pack_left_shift_u8(src_p->fault_elcon, 3u, 0x08u);
    dst_p[0] |= pack_left_shift_u8(src_p->fault_bps, 4u, 0x10u);
    dst_p[0] |= pack_left_shift_u8(src_p->fault_evse, 5u, 0x20u);
    dst_p[0] |= pack_left_shift_u8(src_p->estop, 6u, 0x40u);
    dst_p[0] |= pack_left_shift_u8(src_p->charge_state, 7u, 0x80u);
    dst_p[1] |= pack_right_shift_u8(src_p->charge_state, 1u, 0x01u);
    dst_p[1] |= pack_left_shift_u8(src_p->evse_connected, 1u, 0x02u);
    dst_p[1] |= pack_left_shift_u8(src_p->evse_latch_pressed, 2u, 0x04u);
    dst_p[1] |= pack_left_shift_u8(src_p->evse_state, 3u, 0x38u);
    dst_p[1] |= pack_left_shift_u8(src_p->evsecp_valid, 6u, 0x40u);
    dst_p[1] |= pack_left_shift_u16(src_p->evse_available_current, 7u, 0x80u);
    dst_p[2] |= pack_right_shift_u16(src_p->evse_available_current, 1u, 0xffu);
    dst_p[3] |= pack_right_shift_u16(src_p->evse_available_current, 9u, 0x07u);

    return (4);
}

int charger_can_raw_elcon_interface_status_unpack(
    struct charger_can_raw_elcon_interface_status_t *dst_p,
    const uint8_t *src_p,
    size_t size)
{
    if (size < 4u) {
        return (-EINVAL);
    }

    dst_p->status = unpack_right_shift_u8(src_p[0], 0u, 0x01u);
    dst_p->fault_elcon_watchdog = unpack_right_shift_u8(src_p[0], 1u, 0x02u);
    dst_p->fault_bps_watchdog = unpack_right_shift_u8(src_p[0], 2u, 0x04u);
    dst_p->fault_elcon = unpack_right_shift_u8(src_p[0], 3u, 0x08u);
    dst_p->fault_bps = unpack_right_shift_u8(src_p[0], 4u, 0x10u);
    dst_p->fault_evse = unpack_right_shift_u8(src_p[0], 5u, 0x20u);
    dst_p->estop = unpack_right_shift_u8(src_p[0], 6u, 0x40u);
    dst_p->charge_state = unpack_right_shift_u8(src_p[0], 7u, 0x80u);
    dst_p->charge_state |= unpack_left_shift_u8(src_p[1], 1u, 0x01u);
    dst_p->evse_connected = unpack_right_shift_u8(src_p[1], 1u, 0x02u);
    dst_p->evse_latch_pressed = unpack_right_shift_u8(src_p[1], 2u, 0x04u);
    dst_p->evse_state = unpack_right_shift_u8(src_p[1], 3u, 0x38u);
    dst_p->evsecp_valid = unpack_right_shift_u8(src_p[1], 6u, 0x40u);
    dst_p->evse_available_current = unpack_right_shift_u16(src_p[1], 7u, 0x80u);
    dst_p->evse_available_current |= unpack_left_shift_u16(src_p[2], 1u, 0xffu);
    dst_p->evse_available_current |= unpack_left_shift_u16(src_p[3], 9u, 0x07u);

    return (0);
}

